// calc: profile = rv64imc
// calc: input_max = 4800
// calc: output_max = 8
// calc: mem_kib = 16

// HIP5 scoring calc kernel for HacdsDeFi #3000.
// Deposit (n up to 200) calls this; redeem keeps the single-diamond FitSH path.
// The FitSH five-dimension functions stay in the contract, still used by redeem
// and by the standalone quote_score view.
//
// This is a plain fitshc kernel *module* (not a crate root): the wrapper
// generated by `fitshc` owns `#![no_std]`, `calc_entry`, HALT and the panic
// handler. Build it together with the contract:
//
//   sh build-v3000.sh
//   # fitshc build HacdsDeFi3000.fitsh --calc score_sum=score_sum.rs
//
// Input  = names[6n] || numbers[8n] || visual_genes[10n]   (n = len / 24)
//          names         : 6-byte diamond names, input order
//          numbers       : per-diamond u64 big-endian
//          visual_genes  : per-diamond 10-byte visual gene
// Output = 8-byte big-endian u64 = Σ score(record_i)
//          n = 1 yields that diamond's score.
//
// The HVM call site passes a one-layer list. The calc boundary concatenates
// list elements (Tuple is not a byte string). n <= 200 -> 24*200 = 4800 B,
// which is the declared input_max and is within call_data_size 5120.
// Life gene is not part of the score.
//
// Semantics are Diamond Analyzer v0.1.1: shape + (style | color) + name +
// number, floored at 1. Integer-only, no floats, no hashing.

/// Failure path retained from the standalone kernel: malformed input traps
/// (guest failure) instead of silently returning a bogus sum. `ebreak` is a
/// deterministic trap on every calc profile (forced to the 32-bit encoding
/// for RVC builds, same as the generated wrapper).
fn trap() -> ! {
    loop {
        unsafe {
            core::arch::asm!(".option push\n.option norvc\nebreak\n.option pop");
        }
    }
}

pub fn score_sum(input: &[u8], out: &mut [u8]) -> usize {
    // n names (6 B) || n numbers (8 B) || n visual genes (10 B)
    if input.len() % 24 != 0 {
        trap();
    }
    let n = input.len() / 24;
    let name_end = n * 6;
    let num_end = name_end + n * 8;
    let mut sum: u64 = 0;
    let mut i = 0;
    while i < n {
        let name = &input[i * 6..i * 6 + 6];
        let num = u64::from_be_bytes(
            input[name_end + i * 8..name_end + i * 8 + 8]
                .try_into()
                .unwrap(),
        );
        let vg = &input[num_end + i * 10..num_end + i * 10 + 10];
        sum = sum.wrapping_add(score(name, vg, num));
        i += 1;
    }
    let n = out.len().min(8);
    out[..n].copy_from_slice(&sum.to_be_bytes()[..n]);
    n
}

fn score(name: &[u8], vg: &[u8], num: u64) -> u64 {
    let shape = shape_score(vg);
    let colorish = if shape == 0 {
        style_score(vg)
    } else {
        color_score(vg, name)
    };
    let nl = nameliteral_score(name);
    let nu = numberliteral_score(num);
    let total = shape + colorish + nl + nu;
    if total < 1 {
        1
    } else {
        total
    }
}

/// idx-th hex nibble of the 10-byte visual gene (idx 0..19).
#[inline(always)]
fn vg_hex(vg: &[u8], idx: usize) -> u64 {
    let b = vg[idx / 2] as u64;
    if idx % 2 == 0 {
        b / 16
    } else {
        b % 16
    }
}

fn shape_score(vg: &[u8]) -> u64 {
    let a = vg_hex(vg, 0);
    let b = vg_hex(vg, 1);
    if a != 0 {
        return 0;
    }
    match b {
        1 => 30, // 01 Square
        2 => 30, // 02 Ellipse
        3 => 50, // 03 Heart
        4 => 20, // 04 Triangle
        5 => 30, // 05 Teardrop
        6 => 30, // 06 Circle
        7 => 20, // 07 Rhombus
        8 => 20, // 08 Hexagon
        _ => 0,  // 00 Common / unknown
    }
}

fn style_score(vg: &[u8]) -> u64 {
    let c13 = vg_hex(vg, 14);
    let c14 = vg_hex(vg, 15);
    let c15 = vg_hex(vg, 16);
    let c16 = vg_hex(vg, 17);

    // candidate 1: positional rules, first hit wins (DA order)
    let pos_score = if c13 == c14 && c14 == c15 && c15 == c16 {
        250 // Pure
    } else if c13 == c14 && c14 == c15 && c14 != c16 {
        20 // Left three pure
    } else if c13 == c15 && c15 == c16 && c14 != c13 {
        20 // Left mix pure
    } else if c13 == c14 && c14 == c16 && c15 != c13 {
        20 // Right three pure
    } else if c14 == c15 && c15 == c16 && c14 != c13 {
        20 // Right mix pure
    } else if c16 == c15 && c13 == c14 {
        20 // Color Symmetry
    } else if c16 == c14 && c13 == c15 {
        20 // Half divide
    } else if c15 * 16 + c13 == c14 * 16 + c16 {
        20 // Double mix
    } else if c13 == c14 && c15 != c16 {
        3 // Center color
    } else if c15 == c16 && c14 != c13 {
        3 // Edge color
    } else {
        0
    };

    // candidates 2 + 3: one pass builds the bitmap and the light/dark flags
    let mut bitmap: u32 = 0;
    let mut all_dark = true;
    let mut all_light = true;
    for i in 2..18 {
        let hv = vg_hex(vg, i);
        bitmap |= 1u32 << hv;
        if hv > 4 {
            all_dark = false;
        }
        if hv <= 4 {
            all_light = false;
        }
    }
    let distinct = popcount16(bitmap);
    let cnt_score = match distinct {
        4 => 200,
        5 => 100,
        6 => 50,
        7 => 20,
        14 => 30,
        15 => 100,
        16 => 200,
        _ => 0,
    };
    let dl_score = if all_dark || all_light { 20 } else { 0 };

    pos_score.max(cnt_score).max(dl_score)
}

fn popcount16(mut x: u32) -> u64 {
    x &= 0xFFFF;
    x = x - ((x >> 1) & 0x5555);
    x = (x & 0x3333) + ((x >> 2) & 0x3333);
    x = (x + (x >> 4)) & 0x0F0F;
    x = x + (x >> 8);
    (x & 0x1F) as u64
}

fn color_score(vg: &[u8], name: &[u8]) -> u64 {
    let s = match name[0] {
        b'A' => 7,
        b'B' => 6,
        b'E' => 1,
        b'H' => 8,
        b'I' => 8,
        b'K' => 8,
        b'M' => 2,
        b'N' => 6,
        b'S' => 6,
        b'T' => 8,
        b'U' => 3,
        b'V' => 8,
        b'W' => 3,
        b'X' => 5,
        b'Y' => 3,
        b'Z' => 10,
        _ => 0,
    };
    // light/dark over the 17 nibbles hex[2..19)
    let mut all_dark = true;
    let mut all_light = true;
    for i in 2..19 {
        let v = vg_hex(vg, i);
        if v > 4 {
            all_dark = false;
        }
        if v <= 4 {
            all_light = false;
        }
    }
    let bonus = if all_dark || all_light { 20 } else { 0 };
    s.max(bonus)
}

/// "WTYUIAHXVMEKBSZN" index; non-members map to bit 16 (ignored by the
/// popcount mask, matching the contract's `pow2`/`popcount16` behaviour).
fn letter_idx(c: u8) -> u32 {
    match c {
        b'W' => 0,
        b'T' => 1,
        b'Y' => 2,
        b'U' => 3,
        b'I' => 4,
        b'A' => 5,
        b'H' => 6,
        b'X' => 7,
        b'V' => 8,
        b'M' => 9,
        b'E' => 10,
        b'K' => 11,
        b'B' => 12,
        b'S' => 13,
        b'Z' => 14,
        b'N' => 15,
        _ => 16,
    }
}

fn nameliteral_score(name: &[u8]) -> u64 {
    // longest run of equal adjacent chars
    let mut maxrun: u64 = 1;
    let mut run: u64 = 1;
    for i in 1..6 {
        if name[i] == name[i - 1] {
            run += 1;
            if run > maxrun {
                maxrun = run;
            }
        } else {
            run = 1;
        }
    }
    let mut bitmap: u32 = 0;
    for i in 0..6 {
        bitmap |= 1u32 << letter_idx(name[i]);
    }
    let distinct = popcount16(bitmap);

    let mut best: u64 = 0;
    if maxrun >= 3 {
        let v = match maxrun {
            6 => 200, // six repeat
            5 => 50,  // Penta repeat
            4 => 10,  // Quadro repeat
            _ => 2,   // Triple repeat
        };
        if v > best {
            best = v;
        }
    }
    if distinct == 2 {
        if 10 > best {
            best = 10;
        }
    } else if distinct == 3 {
        if 3 > best {
            best = 3;
        }
    }
    if name[0..3] == name[3..6] {
        if 20 > best {
            best = 20;
        }
    }
    if name[0] == name[5] && name[1] == name[4] && name[2] == name[3] {
        if 10 > best {
            best = 10;
        }
    }
    if name[0] == name[1] && name[3] == name[4] {
        if 10 > best {
            best = 10;
        }
    }
    if name[1] == name[2] && name[4] == name[5] {
        if 10 > best {
            best = 10;
        }
    }
    best
}

fn numberliteral_score(num: u64) -> u64 {
    let mut best: u64 = 0;
    if num < 10 {
        best = 30; // Single num
    }
    // decimal digits (num <= u64 → <= 20 digits)
    let mut digits = [0u8; 20];
    let mut n = 0usize;
    let mut x = num;
    if x == 0 {
        digits[0] = b'0';
        n = 1;
    } else {
        while x > 0 {
            digits[n] = b'0' + (x % 10) as u8;
            x /= 10;
            n += 1;
        }
        digits[..n].reverse();
    }
    let d = &digits[..n];

    // Repetition: every digit the same
    let mut bitmap: u32 = 0;
    for i in 0..n {
        bitmap |= 1u32 << (d[i] - b'0');
    }
    if popcount16(bitmap) == 1 {
        if 50 > best {
            best = 50;
        }
    }
    // Serial num: strictly +1 or strictly -1 across the whole string
    if is_sequential(d) {
        if 25 > best {
            best = 25;
        }
    }
    // Number Symmetry: palindrome
    if is_symmetric(d) {
        if 10 > best {
            best = 10;
        }
    }
    // Tail runs (>= 4)
    let mut maxrun: u64 = 1;
    let mut run: u64 = 1;
    for i in 1..n {
        if d[i] == d[i - 1] {
            run += 1;
            if run > maxrun {
                maxrun = run;
            }
        } else {
            run = 1;
        }
    }
    if maxrun >= 4 {
        let v = match maxrun {
            7 => 200,
            6 => 100,
            5 => 50,
            _ => 20,
        };
        if v > best {
            best = v;
        }
    }
    best
}

fn is_sequential(d: &[u8]) -> bool {
    if d.len() < 2 {
        return true;
    }
    let mut up = true;
    let mut down = true;
    for i in 1..d.len() {
        let cur = d[i];
        let pre = d[i - 1];
        if cur <= pre {
            up = false;
        } else if cur - pre != 1 {
            up = false;
        }
        if cur >= pre {
            down = false;
        } else if pre - cur != 1 {
            down = false;
        }
    }
    up || down
}

fn is_symmetric(d: &[u8]) -> bool {
    let n = d.len();
    for i in 0..n / 2 {
        if d[i] != d[n - 1 - i] {
            return false;
        }
    }
    true
}